/* Speaking Practice — question banks, topics and model answers. */
window.SPEAKING_PRACTICE_UI = (() => {
  'use strict';

  const DATA = () => window.SPEAKING_PRACTICE || { random: [], thought: [], ielts: { 1: [], 2: [], 3: [] }, topicMeta: [] };
  let root = null, els = {}, topics = [], mounted = false;
  const state = { mode: 'random', topicIndex: null, topicName: '', selectedTopicIndex: 0, prompt: '', cues: [], lastIndexByKey: {} };

  const esc = (s = '') => String(s).replace(/[&<>'"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', "'": '&#39;', '"': '&quot;' }[c]));
  const q = sel => root.querySelector(sel);
  const qa = sel => [...root.querySelectorAll(sel)];
  const scrollTo = el => { if (el && typeof el.scrollIntoView === 'function') el.scrollIntoView({ behavior: 'smooth', block: 'start' }); };

  function buildTopics() {
    const d = DATA();
    topics = (d.topicMeta || []).map(([name, category, icon], i) => ({ name, category, icon, questions: (d.random || []).slice(i * 10, i * 10 + 10) }));
  }

  function shell() {
    const d = DATA();
    const total = (d.random || []).length + (d.thought || []).length + (d.ielts[1] || []).length + (d.ielts[2] || []).length + (d.ielts[3] || []).length;
    return `
<section class="sp-hero">
  <div>
    <h1>Speaking Practice</h1>
    <p>Pick a question, answer aloud, then explore a model answer to compare ideas, vocabulary and natural phrasing.</p>
  </div>
  <div class="sp-hero-stat">
    <span class="study-pill"><b>${total}</b> questions</span>
    <span class="study-pill"><b>${topics.length}</b> topics</span>
  </div>
</section>

<div class="sp-modes" role="tablist" aria-label="Practice mode">
  <button class="sp-mode active" type="button" data-mode="random" id="sp-tab-random" role="tab" aria-controls="spStage"><i>↻</i>Random</button>
  <button class="sp-mode" type="button" data-mode="ielts" id="sp-tab-ielts" role="tab" aria-controls="spStage"><i>I</i>IELTS</button>
  <button class="sp-mode" type="button" data-mode="topics" id="sp-tab-topics" role="tab" aria-controls="spTopics"><i>#</i>Topics</button>
  <button class="sp-mode" type="button" data-mode="thought" id="sp-tab-thought" role="tab" aria-controls="spStage"><i>→</i>Scenarios</button>
</div>

<div class="sp-controls">
  <select class="sp-select" id="spPart" aria-label="IELTS part" hidden>
    <option value="1">Part 1</option><option value="2">Part 2</option><option value="3">Part 3</option>
  </select>
  <button class="sp-btn grow" type="button" id="spNew">New question ↻</button>
</div>

<section class="sp-stage" id="spStage" role="tabpanel" aria-labelledby="sp-tab-random">
  <div class="sp-kicker" id="spMeta">RANDOM</div>
  <h2 class="sp-question" id="spQuestion"></h2>
  <div class="sp-cues" id="spCues"></div>
  <div class="sp-answer-actions">
    <button class="sp-btn primary sp-answer-btn" type="button" id="spAnswerBtn">Show model answer</button>
  </div>
  <div class="sp-model-answer" id="spAnswer" hidden>
    <h3 class="model-answer-title">Advanced Model Answer</h3>
    <p id="spAnswerText"></p>
  </div>
</section>

<section class="sp-topics" id="spTopics" role="tabpanel" aria-labelledby="sp-tab-topics" hidden>
  <div class="sp-topic-tools">
    <input class="sp-topic-search" id="spTopicSearch" type="search" placeholder="Search topics…" autocomplete="off" aria-label="Search topics">
    <span class="sp-topic-count" id="spTopicCount"></span>
  </div>
  <div class="sp-topic-layout">
    <div class="sp-topic-grid" id="spTopicGrid"></div>
    <aside class="sp-topic-detail" id="spTopicDetail"></aside>
  </div>
</section>`;
  }

  function part() { return Number(els.part.value || 1); }
  function pick(list, key) {
    if (!list || !list.length) return '';
    if (list.length === 1) return list[0];
    let i = Math.floor(Math.random() * list.length);
    if (i === state.lastIndexByKey[key]) i = (i + 1 + Math.floor(Math.random() * (list.length - 1))) % list.length;
    state.lastIndexByKey[key] = i;
    return list[i];
  }

  function topicForPrompt(prompt) {
    const hit = topics.find(t => t.questions.includes(prompt));
    return hit ? hit.name : 'the topic';
  }

  function hideAnswer() {
    if (!els.answer) return;
    els.answer.hidden = true;
    els.answerBtn.textContent = 'Show model answer';
    els.answerBtn.setAttribute('aria-expanded', 'false');
  }

  function setPrompt(next = true) {
    if (!next && state.prompt) return;
    const d = DATA();
    state.cues = [];
    if (state.mode === 'ielts') {
      const p = part();
      const item = pick(d.ielts[p], 'ielts-' + p);
      if (p === 2 && item && typeof item === 'object') { state.prompt = item.q; state.cues = item.cues || []; }
      else state.prompt = item;
      els.meta.textContent = `IELTS PART ${p} · ${(d.ielts[p] || []).length} QUESTIONS`;
    } else if (state.mode === 'topic') {
      const t = topics[state.topicIndex ?? 0];
      state.topicName = t.name;
      state.prompt = pick(t.questions, 'topic-' + (state.topicIndex ?? 0));
      els.meta.textContent = `TOPIC · ${t.name.toUpperCase()} · ${t.questions.length} QUESTIONS`;
    } else {
      const bank = state.mode === 'thought' ? d.thought : d.random;
      state.prompt = pick(bank, state.mode);
      state.topicName = state.mode === 'random' ? topicForPrompt(state.prompt) : '';
      els.meta.textContent = state.mode === 'thought' ? `SCENARIOS · ${(d.thought || []).length} QUESTIONS` : `RANDOM · ${(d.random || []).length} QUESTIONS`;
    }
    paintPrompt();
  }

  function paintPrompt() {
    els.question.textContent = state.prompt || '';
    els.cues.innerHTML = state.cues.length ? '<ul>' + state.cues.map(c => '<li>' + esc(c) + '</li>').join('') + '</ul>' : '';
    hideAnswer();
  }

  function markTab(mode) {
    const tab = mode === 'topic' ? 'topics' : mode;
    qa('.sp-mode').forEach(b => {
      b.classList.toggle('active', b.dataset.mode === tab);
      b.setAttribute('aria-selected', String(b.dataset.mode === tab));
      b.tabIndex=b.dataset.mode===tab?0:-1;
      if(b.dataset.mode===tab&&!els.stage.hidden)els.stage.setAttribute('aria-labelledby',b.id);
    });
  }

  function showTopics(on) {
    els.topics.hidden = !on;
    els.stage.hidden = on;
    els.controls.hidden = on;
  }

  function setMode(mode) {
    if (mode === 'topics') { markTab('topics'); showTopics(true); renderTopics(els.topicSearch.value); return; }
    showTopics(false);
    state.mode = mode; state.topicIndex = null; state.topicName = '';
    markTab(mode);
    els.part.hidden = mode !== 'ielts';
    setPrompt();
  }

  function renderTopics(query = '') {
    const s = String(query || '').trim().toLowerCase();
    const rows = topics.map((t, i) => ({ t, i })).filter(({ t }) => !s || (t.name + ' ' + t.category).toLowerCase().includes(s));
    els.topicCount.textContent = rows.length + ' topics';
    els.topicGrid.innerHTML = rows.length ? rows.map(({ t, i }) => `
      <button class="sp-topic-card${state.selectedTopicIndex === i ? ' active' : ''}" type="button" data-t="${i}">
        <span class="sp-topic-icon">${esc(t.icon)}</span>
        <span class="sp-topic-copy"><strong>${esc(t.name)}</strong><span>${esc(t.category)} · 10 questions</span></span>
      </button>`).join('') : '<div class="sp-topic-empty">No matching topics.</div>';
    els.topicGrid.querySelectorAll('[data-t]').forEach(b => b.addEventListener('click', () => selectTopic(Number(b.dataset.t), true)));
  }

  function selectTopic(i, scroll = false) {
    const t = topics[i];
    if (!t) return;
    state.selectedTopicIndex = i;
    els.topicDetail.innerHTML = `
      <div class="sp-topic-head">
        <div class="sp-topic-title"><span class="sp-topic-icon">${esc(t.icon)}</span><div><h2>${esc(t.name)}</h2><p>${esc(t.category)} · 10 questions</p></div></div>
        <button class="sp-btn primary" type="button" id="spTopicRandom">Pick a question</button>
      </div>
      <div class="sp-topic-qs">${t.questions.map((qq, n) => `<button class="sp-topic-q" type="button" data-q="${n}"><b>${String(n + 1).padStart(2, '0')}</b><span>${esc(qq)}</span></button>`).join('')}</div>`;
    els.topicDetail.querySelector('#spTopicRandom').addEventListener('click', () => startTopic(i));
    els.topicDetail.querySelectorAll('[data-q]').forEach(b => b.addEventListener('click', () => startTopic(i, Number(b.dataset.q))));
    renderTopics(els.topicSearch.value);
    if (scroll && window.innerWidth <= 1000) scrollTo(els.topicDetail);
  }

  function startTopic(i, qi = null) {
    const t = topics[i];
    if (!t) return;
    showTopics(false);
    state.mode = 'topic'; state.topicIndex = i; state.topicName = t.name; state.cues = [];
    state.prompt = qi == null ? pick(t.questions, 'topic-' + i) : t.questions[qi];
    markTab('topic');
    els.part.hidden = true;
    els.meta.textContent = `TOPIC · ${t.name.toUpperCase()} · 10 QUESTIONS`;
    paintPrompt();
    scrollTo(els.stage);
  }

  function sampleAnswer(){
    return (window.SPEAKING_PRACTICE_AUDIO||[]).find(item=>item.question===state.prompt)?.answer||'';
  }

  function practiceTextHtml(text, phrases = []) {
    const raw = String(text || '');
    const matches = phrases.map(phrase => ({ text: phrase.en, index: raw.indexOf(phrase.en) }))
      .filter(match => match.index >= 0 && match.text)
      .sort((a, b) => a.index - b.index || b.text.length - a.text.length);
    let cursor = 0, result = '';
    matches.forEach(match => {
      if (match.index < cursor) return;
      result += esc(raw.slice(cursor, match.index)) + '<strong class="key-phrase">' + esc(match.text) + '</strong>';
      cursor = match.index + match.text.length;
    });
    return result + esc(raw.slice(cursor));
  }

  function practiceMeaningsHtml(phrases = []) {
    if (!phrases.length) return '';
    return '<section class="phrase-meanings" aria-label="Key words and phrases"><h4 class="section-label key-phrase-meanings-title">Key words and phrases</h4><dl class="phrases">' + phrases.map(phrase => '<div class="phrase"><dt>' + esc(phrase.en) + '</dt><dd>' + esc(phrase.meaning) + '</dd></div>').join('') + '</dl></section>';
  }

  function practiceAnswerHtml(item, fallbackAnswer = '') {
    const simple = item && item.simpleAnswer;
    const simpleHtml = simple ? '<section class="model-version simple-model"><h3 class="model-answer-title">Simple Model Answer</h3><p id="spSimpleAnswerText">' + practiceTextHtml(simple.text, simple.phrases) + '</p>' + practiceMeaningsHtml(simple.phrases) + '</section>' : '';
    const advanced = item ? item.answer : fallbackAnswer;
    const advancedPhrases = item && item.answerPhrases || [];
    return simpleHtml + '<section class="model-version advanced-model"><h3 class="model-answer-title">Advanced Model Answer</h3><p id="spAnswerText">' + practiceTextHtml(advanced, advancedPhrases) + '</p>' + practiceMeaningsHtml(advancedPhrases) + '</section>';
  }

  function toggleAnswer() {
    const opening = els.answer.hidden;
    if (opening) {
      const item = (window.SPEAKING_PRACTICE_AUDIO || []).find(entry => entry.question === state.prompt);
      els.answer.innerHTML = practiceAnswerHtml(item, item ? item.answer : sampleAnswer());
      els.answerText = q('#spAnswerText');
      els.answer.hidden = false;
      els.answerBtn.textContent = 'Hide model answer';
      els.answerBtn.setAttribute('aria-expanded', 'true');
      scrollTo(els.answer);
    } else hideAnswer();
  }

  function mount(container) {
    const previous = history.state?.practice;
    const saved = previous?.mode === 'audio' ? null : previous;
    unmount();
    root = container;
    root.className = 'sp-main';
    buildTopics();
    root.innerHTML = shell();
    mounted = true;
    els = {
      meta: q('#spMeta'), question: q('#spQuestion'), cues: q('#spCues'), part: q('#spPart'), newBtn: q('#spNew'),
      stage: q('#spStage'), controls: q('.sp-controls'), answerBtn: q('#spAnswerBtn'), answer: q('#spAnswer'), answerText: q('#spAnswerText'),
      topics: q('#spTopics'), topicSearch: q('#spTopicSearch'), topicCount: q('#spTopicCount'), topicGrid: q('#spTopicGrid'), topicDetail: q('#spTopicDetail')
    };

    qa('.sp-mode').forEach(b => b.addEventListener('click', () => setMode(b.dataset.mode)));
    qa('.sp-mode').forEach(b=>b.addEventListener('keydown',event=>{const tabs=qa('.sp-mode'),i=tabs.indexOf(b);let n;if(event.key==='ArrowRight')n=(i+1)%tabs.length;else if(event.key==='ArrowLeft')n=(i-1+tabs.length)%tabs.length;else if(event.key==='Home')n=0;else if(event.key==='End')n=tabs.length-1;else return;event.preventDefault();tabs[n].focus();setMode(tabs[n].dataset.mode);}));
    els.newBtn.addEventListener('click', () => setPrompt());
    els.part.addEventListener('change', () => setPrompt());
    els.answerBtn.addEventListener('click', toggleAnswer);
    els.topicSearch.addEventListener('input', () => renderTopics(els.topicSearch.value));

    renderTopics();
    selectTopic(state.selectedTopicIndex || 0, false);
    state.mode = saved?.mode || 'random';
    state.topicIndex = saved?.topicIndex ?? null;
    state.topicName = saved?.topicName || '';
    state.selectedTopicIndex = saved?.selectedTopicIndex || 0;
    if(saved?.part)els.part.value=saved.part;
    markTab(state.mode);
    els.part.hidden = state.mode !== 'ielts';
    setPrompt();
    if(saved?.prompt&&(window.SPEAKING_PRACTICE_AUDIO||[]).some(x=>x.question===saved.prompt)){
      state.prompt=saved.prompt;state.cues=saved.cues||[];paintPrompt();
      if(saved.answerOpen)toggleAnswer();
    }
    if(saved?.topicSearch){els.topicSearch.value=saved.topicSearch;renderTopics(saved.topicSearch);}
    selectTopic(state.selectedTopicIndex,false);
    if(saved?.topicsVisible){markTab('topics');showTopics(true);}

  }

  function unmount() {
    if (!mounted) return;
    mounted = false;
    root = null;
    els = {};
  }

  return { mount, unmount, snapshot:()=>mounted?{mode:state.mode,topicIndex:state.topicIndex,topicName:state.topicName,selectedTopicIndex:state.selectedTopicIndex,prompt:state.prompt,cues:state.cues,part:els.part.value,answerOpen:!els.answer.hidden,topicsVisible:!els.topics.hidden,topicSearch:els.topicSearch.value}:null };
})();

;

